#include <chrono>
#include <sstream>
#include <format>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    using namespace std::chrono;
    sys_seconds system{seconds{0}};
    auto utc = utc_clock::from_sys(system);
    assert(utc_clock::to_sys(utc) == system);
    auto tai = tai_clock::from_utc(utc);
    assert(tai_clock::to_utc(tai) == utc);
    auto gps = gps_clock::from_utc(utc);
    assert(gps_clock::to_utc(gps) == utc);
    assert(clock_cast<utc_clock>(system) == utc);
    assert((clock_time_conversion<utc_clock, system_clock>{}(system) == utc));
    leap_second_info info = get_leap_second_info(utc);
    assert(!info.is_leap_second);
    const auto &leaps = get_tzdb().leap_seconds;
    if (!leaps.empty()) {
        const auto &leap = leaps.front();
        assert(leap == leap);
        (void)leap.date();
    }
    std::ostringstream text;
    text << utc << tai << gps;
    assert(!text.str().empty());
}
